/// One **required** method per labelled alternative.
///
/// Each takes the alternative's bindings, already evaluated — the
/// generated evaluator does the walking. Nothing is defaulted: adding
/// an alternative to the grammar must break the build until a handler
/// exists.
pub trait Handlers: Operators + Sized {

    /// `program` — from `rule program = SOI stmts:stmt* EOI -> doc`.
    /// * `stmts` — the value of the `stmt` rule, already evaluated (repeated in the grammar; items that failed and were already reported are omitted)
    fn program(&mut self, stmts: Vec<Self::Out>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_bind` — from `rule stmt = "let" name:IDENT "=" value:expr ";" -> bind`.
    /// * `name` — the text of the `IDENT` token
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_bind(&mut self, name: &str, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_print` — from `rule stmt = "print" value:expr ";" -> print`.
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_print(&mut self, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_iff` — from `rule stmt = "if" cond:expr "then" lazy body:stmt -> iff`.
    /// * `cond` — the value of the `expr` rule, already evaluated
    /// * `body` — the `stmt` rule, **unevaluated** — `.eval(host, cx)?` runs it
    fn stmt_iff(&mut self, cond: Self::Out, body: &Rc<Stmt>, cx: &mut Ctx) -> Result<Self::Out>;

    /// `stmt_eval` — from `rule stmt = value:expr ";" -> eval`.
    /// * `value` — the value of the `expr` rule, already evaluated
    fn stmt_eval(&mut self, value: Self::Out, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_num` — from `rule primary = digits:NUMBER -> num`.
    /// * `digits` — the text of the `NUMBER` token
    fn primary_num(&mut self, digits: &str, cx: &mut Ctx) -> Result<Self::Out>;

    /// `primary_var` — from `rule primary = name:IDENT -> var place`.
    /// * `name` — the text of the `IDENT` token
    fn primary_var(&mut self, name: &str, cx: &mut Ctx) -> Result<Self::Out>;
}

