/// Runs a node.
///
/// Implemented for every generated AST type, so a `lazy` parameter is
/// run with `.eval(host, cx)?` at whatever moment the handler chooses —
/// including never, or more than once.
pub trait Eval {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out>;
}

/// Evaluates `program`, from `SOI stmts:stmt* EOI -> doc`.
pub fn eval_program<H: Handlers>(host: &mut H, node: &Program, cx: &mut Ctx) -> Result<H::Out> {
    // Entering the node's span is what makes `cx.err(..)` inside the
    // handler locate itself with no span bookkeeping (DESIGN.md §7).
    cx.enter(node.span);
    let result = eval_program_inner(host, node, cx);
    cx.leave();
    result
}

fn eval_program_inner<H: Handlers>(
    host: &mut H,
    node: &Program,
    cx: &mut Ctx,
) -> Result<H::Out> {
    let stmts = {
                let mut v = Vec::new();
                for n in &node.stmts {
                    match eval_stmt(host, n, cx) {
                        Ok(x) => v.push(x),
                        Err(Error::AlreadyReported) => continue,
                        Err(e) => return Err(e),
                    }
                }
                v
            };
    host.program(stmts, cx)
}

impl Eval for Program {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out> {
        eval_program(host, self, cx)
    }
}

/// Evaluates a `stmt` by handing off to whichever alternative matched.
pub fn eval_stmt<H: Handlers>(host: &mut H, node: &Stmt, cx: &mut Ctx) -> Result<H::Out> {
    match node {
        Stmt::Bind(n) => eval_stmt_bind(host, n, cx),
        Stmt::Print(n) => eval_stmt_print(host, n, cx),
        Stmt::Iff(n) => eval_stmt_iff(host, n, cx),
        Stmt::Eval(n) => eval_stmt_eval(host, n, cx),
        // A region the parse recovered from: report once, then
        // poison, so one bad statement is one message rather than
        // that plus every consequence of it (DESIGN.md §5.5).
        Stmt::Error(span) => {
            cx.report(Diagnostic::error("could not parse this `stmt`").at(*span));
            Err(Error::AlreadyReported)
        }
    }
}

impl Eval for Stmt {
    fn eval<H: Handlers>(&self, host: &mut H, cx: &mut Ctx) -> Result<H::Out> {
        eval_stmt(host, self, cx)
    }
}

